package com.jksalcedo.passvault.core.backup

/**
 * Builds regexes that match backup files generated by a user-configured filename pattern.
 *
 * The pattern can contain `{timestamp}` anywhere. Everything else is treated literally.
 * Matching is intentionally limited to known backup extensions and supports the `_copyN`
 * suffix used when several copies are created (or when a name collides).
 */
object BackupFileMatcher {

    private const val TIMESTAMP_TOKEN = "{timestamp}"

    private val EXTENSIONS = listOf("json", "csv", "kdbx", "chrome_csv")

    /**
     * Builds a regex for a single filename pattern.
     */
    fun buildRegex(pattern: String): Regex {
        // Split around {timestamp}, quote each literal part, then join with a wildcard.
        val quotedPattern = pattern
            .split(TIMESTAMP_TOKEN)
            .joinToString(".*") { Regex.escape(it) }

        val extensions = EXTENSIONS.joinToString("|") { Regex.escape(it) }
        return Regex(
            pattern = "^$quotedPattern(?:_copy\\d+)?\\.(?:$extensions)$",
            option = RegexOption.IGNORE_CASE
        )
    }

    /**
     * Builds a regex for each non-blank pattern.
     */
    fun buildRegexes(patterns: Collection<String>): List<Regex> {
        return patterns
            .filter { it.isNotBlank() }
            .distinct()
            .map(::buildRegex)
    }

    /**
     * Checks a single pattern against a file name.
     */
    fun matches(pattern: String, fileName: String): Boolean {
        return buildRegex(pattern).matches(fileName)
    }

    /**
     * Checks a file name against any of the supplied patterns.
     */
    fun matchesAny(patterns: Collection<String>, fileName: String): Boolean {
        return buildRegexes(patterns).any { it.matches(fileName) }
    }

    /**
     * Produces unique file names for a backup run.
     *
     * When [count] is 1 the plain `baseName.ext` is used unless it already exists; in that
     * case `_copy2`, `_copy3`, ... are tried. When several copies are requested, `_copy1`,
     * `_copy2`, ... are generated, skipping any name that is already present.
     */
    fun uniqueFileNames(
        baseName: String,
        extension: String,
        count: Int,
        existingNames: Set<String>
    ): List<String> {
        val taken = existingNames.mapTo(mutableSetOf()) { it.lowercase() }
        val safeBase = baseName.ifBlank { "passvault_backup" }
        val safeExtension = extension.removePrefix(".").ifBlank { "json" }

        if (count <= 1) {
            val plain = "$safeBase.$safeExtension"
            if (taken.add(plain.lowercase())) return listOf(plain)

            var copy = 2
            while (true) {
                val candidate = "${safeBase}_copy$copy.$safeExtension"
                if (taken.add(candidate.lowercase())) return listOf(candidate)
                copy++
            }
        }

        val result = mutableListOf<String>()
        var copy = 1
        while (result.size < count) {
            val candidate = "${safeBase}_copy$copy.$safeExtension"
            if (taken.add(candidate.lowercase())) {
                result.add(candidate)
            }
            copy++
        }
        return result
    }
}
